// @ts-nocheck
import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

async function invariant(h) {
  assert.equal((await h.inFlight()).length, 0);
  let paid = 0;
  for (const id of ['a', 'b', 'c']) {
    const c = await h.cart(id);
    if (c?.status === 'paid') paid += c.items;
  }
  const s = await h.stock();
  assert.equal(s.reserved, paid);
  assert.equal(s.available + s.reserved, 2);
  assert.equal((await h.payments()).charged, paid);
}

test('happy path', async () => {
  const h = await createHost();
  assert.deepEqual(await h.open('a'), { ok: true });
  assert.equal((await h.open('a')).ok, false);
  assert.equal((await h.add('x')).ok, false);
  assert.equal((await h.checkout('a')).ok, false);
  await h.add('a'); await h.add('a');
  assert.equal((await h.add('a')).ok, false);
  await h.checkout('a');
  const m = await h.inFlight();
  assert.equal(m.length, 1);
  assert.deepEqual({ ...m[0], id: 0 }, { id: 0, from: 'a', to: 'inventory', action: 'Reserve', data: { from: 'a', qty: 2 } });
  await h.deliver(m[0].id);
  assert.equal((await h.cart('a')).status, 'paying');
  await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'paid', items: 2 });
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2 });
  assert.equal(await h.cart('zz'), null);
  await invariant(h);
});

test('out of stock, decline, cancel', async () => {
  const h = await createHost();
  for (const id of ['a', 'b', 'c']) { await h.open(id); await h.add(id); await h.add(id); await h.checkout(id); }
  await h.declineCards();
  assert.equal((await h.declineCards()).ok, false);
  assert.deepEqual(await h.cancel('c'), { ok: true });
  assert.equal((await h.cart('c')).status, 'cancelling');
  assert.equal((await h.cancel('c')).ok, false);
  await h.deliverAll();
  await invariant(h);
  assert.equal((await h.stock()).available, 2);
});

test('random orders keep invariant', async () => {
  for (let seed = 0; seed < 500; seed++) {
    const h = await createHost();
    let r = seed * 7919 + 1;
    const rnd = (n) => { r = (r * 1103515245 + 12345) % 2147483648; return r % n; };
    for (let step = 0; step < 40; step++) {
      const id = ['a', 'b', 'c'][rnd(3)];
      const k = rnd(8);
      if (k === 0) await h.open(id);
      else if (k === 1) await h.add(id);
      else if (k === 2) await h.checkout(id);
      else if (k === 3) await h.cancel(id);
      else if (k === 4) rnd(2) ? await h.declineCards() : await h.acceptCards();
      else {
        const m = await h.inFlight();
        if (m.length) await h.deliver(m[rnd(m.length)].id);
      }
    }
    await h.deliverAll();
    await invariant(h);
  }
});

