import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

async function invariant(h) {
  assert.equal((await h.inFlight()).length, 0);
  let paid = 0;
  for (const id of ['a', 'b', 'c']) {
    const c = await h.cart(id);
    if (c?.status === 'paid') paid += c.items;
  }
  const s = await h.stock();
  assert.equal(s.reserved, paid);
  assert.equal(s.available + s.reserved, 2);
  assert.equal((await h.payments()).charged, paid);
}

test('happy path', async () => {
  const h = await createHost();
  assert.deepEqual(await h.open('a'), { ok: true });
  assert.equal((await h.open('a')).ok, false);
  assert.equal((await h.add('x')).ok, false);
  assert.equal((await h.checkout('a')).ok, false);
  await h.add('a'); await h.add('a');
  assert.equal((await h.add('a')).ok, false);
  await h.checkout('a');
  const m = await h.inFlight();
  assert.equal(m.length, 1);
  assert.deepEqual({ ...m[0], id: 0 }, { id: 0, from: 'a', to: 'inventory', action: 'Reserve', data: { from: 'a', qty: 2 } });
