    if (pay.declining || !(amount > 0) || pay.charged + amount > CHARGE_LIMIT) {
      send(PAYMENTS, from, 'Declined', {});
    } else {
      pay.charged += amount;
      send(PAYMENTS, from, 'Charged', {});
