  await h.deliver((await h.inFlight())[0].id);
  assert.equal((await h.cart('a')).status, 'paying');
  await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'paid', items: 2 });
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2 });
  assert.equal(await h.cart('zz'), null);
  await invariant(h);
});

test('out of stock, decline, cancel', async () => {
  const h = await createHost();
  for (const id of ['a', 'b', 'c']) { await h.open(id); await h.add(id); await h.add(id); await h.checkout(id); }
  await h.declineCards();
  assert.equal((await h.declineCards()).ok, false);
  assert.deepEqual(await h.cancel('c'), { ok: true });
  assert.equal((await h.cart('c')).status, 'cancelling');
  assert.equal((await h.cancel('c')).ok, false);
  await h.deliverAll();
  await invariant(h);
  const statuses = await Promise.all(['a', 'b', 'c'].map(async (id) => (await h.cart(id)).status));
  assert.deepEqual(statuses.sort(), ['cancelled', 'declined', 'failed']);
  const dec = (await h.cart('a')).status === 'declined' ? 'a' : 'b';
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2 });
  for (const f of ['add', 'checkout', 'cancel', 'returnCart']) assert.equal((await h[f](dec)).ok, false);
  assert.equal((await h.retry('c')).ok, false);
  assert.equal((await h.abandon('c')).ok, false);
  assert.deepEqual(await h.retry(dec), { ok: true });
  assert.equal((await h.cart(dec)).status, 'paying');
  await h.deliverAll();
  assert.equal((await h.cart(dec)).status, 'declined');
  await h.acceptCards();
  await h.retry(dec); await h.deliverAll();
  assert.equal((await h.cart(dec)).status, 'paid');
  await invariant(h);
  await h.returnCart(dec); await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
});

